<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {runs} from '../stores/runs';import PageHeading from '../components/common/PageHeading.vue';import BudgetStrip from '../components/BudgetStrip.vue';import MorrisPlot from '../components/MorrisPlot.vue';import SobolBars from '../components/SobolBars.vue';import WarningNotes from '../components/WarningNotes.vue';const selected=ref('load');onMounted(runs.load);const result=computed(()=>runs.items.value.find(r=>r.id==='demo-run')?.result);</script><template><PageHeading index="00 / 因子总览" title="看清影响，也保留采样的边界。" note="XH-C06六因子冷却电耗模拟代理。Morris筛查基本效应，Sobol比较方差贡献；局部斜率与全局指数分开解释。"/><template v-if="result"><WarningNotes :rows="result.warnings"/><BudgetStrip :result="result"/><div class="chart-layout"><section><div class="section-heading"><h2>绝对影响，与效应的离散</h2><span>MORRIS / μ* × σ</span></div><MorrisPlot :rows="result.metrics" :selected="selected" @select="selected=$event"/></section><aside class="index-panel"><p class="eyebrow">GLOBAL VARIANCE NOTE</p><h2>一阶与总效应，一起核对</h2><SobolBars :rows="result.metrics"/></aside></div><div class="study-ribbon"><b>受控多项式，不执行表达式。</b><p>{{result.assumptions}}</p><a href="#/results">打开指数、EE与网格轨迹底稿 ↗</a></div></template></template>
